import static org.junit.Assert.*;

public class MutableDateTime_addHours_TriageGen0Test {

    @Test
    public void testAddHours_PositiveValue() {
        // Test adding positive hours (not 1)
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);
        dt.addHours(5);
        assertEquals(15, dt.getHourOfDay());
        assertEquals(2023, dt.getYear());
    }

    @Test
    public void testAddHours_NegativeValue() {
        // Test adding negative hours (not 1)
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);
        dt.addHours(-3);
        assertEquals(7, dt.getHourOfDay());
    }

    @Test
    public void testAddHours_ZeroValue() {
        // Test adding zero hours (not 1)
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);
        long originalMillis = dt.getMillis();
        dt.addHours(0);
        assertEquals(originalMillis, dt.getMillis());
    }

    @Test
    public void testAddHours_OneValue() {
        // Test the specific branch where hours == 1
        // The implementation says: if (hours != 1) { ... }
        // If hours is 1, the method does nothing.
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);
        long originalMillis = dt.getMillis();
        dt.addHours(1);
        assertEquals("When hours is 1, the method should not change the value based on the current implementation logic", 
                     originalMillis, dt.getMillis());
    }

    @Test
    public void testAddHours_CrossDayBoundary() {
        // Test adding hours that cross into the next day
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 23, 0, 0, 0);
        dt.addHours(2);
        assertEquals(1, dt.getDayOfMonth()); // Should be Jan 2nd
        assertEquals(1, dt.getHourOfDay());
        assertEquals(2, dt.getDayOfMonth());
    }

    @Test
    public void testAddHours_LargeValue() {
        // Test adding a large number of hours
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 0, 0, 0, 0);
        // 24 * 2 = 48 hours
        dt.addHours(48);
        assertEquals(3, dt.getDayOfMonth());
        assertEquals(0, dt.getHourOfDay());
    }
}
